function yourFunction(params) {
    for(const organisation of params.allOrganisation){
        if(organisation.properties.name===params.requiredOrganisation){
            return {"result": {organisationID: organisation.id, exists: true}}
        }
    }
    return {"result": {exists: false}}
}

